import groovy.json.*
import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets
import java.text.SimpleDateFormat
import java.util.*
import org.apache.commons.lang3.StringEscapeUtils

def flowFile = session.get()
if (flowFile == null) {
    return
}

def raw = ''
try {
    def data = ''
    session.read(flowFile, { inputStream ->
        data = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    } as InputStreamCallback)

    raw = data

    def parsedJson = new JsonSlurper().parseText(StringEscapeUtils.unescapeJava(data).trim())
    def packetList = parsedJson.packet

    if (!packetList || packetList.isEmpty()) {
        throw new IllegalArgumentException("No packets found in payload")
    }

    def combinedMap = [:]

    // 1. Take base metadata from the first packet entry
    def firstPacket = packetList[0]
    firstPacket.each { key, value ->
        if (!['humidity', 'temperature', 'windDirection', 'windSpeed', 'rain_qty', 'date_time', 'isodate'].contains(key)) {
            combinedMap.put(key, value)
        }
    }

    // 2. Add 'date' from root JSON or fallback to the first packet's isodate
    combinedMap.put("date", parsedJson.date ?: firstPacket.isodate ?: "")

    // 3. Add current IST timestamp
    SimpleDateFormat istFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")
    istFormat.setTimeZone(TimeZone.getTimeZone("IST"))
    combinedMap.put("updated_time", istFormat.format(new Date()))

    // 4. Always guarantee 24 slots (hour0 to hour23)
    for (int i = 0; i < 24; i++) {
        def packet = (i < packetList.size()) ? packetList[i] : [:]

        combinedMap.put("humidity_hour${i}".toString(), packet.humidity ?: "")
        combinedMap.put("temperature_hour${i}".toString(), packet.temperature ?: "")
        combinedMap.put("windDirection_hour${i}".toString(), packet.windDirection ?: "")
        combinedMap.put("windSpeed_hour${i}".toString(), packet.windSpeed ?: "")
        combinedMap.put("rain_qty_hour${i}".toString(), packet.rain_qty ?: "")
    }

    def finalContent = JsonOutput.toJson(combinedMap)

    def updatedFlowFile = session.putAttribute(flowFile, 'LSGName', firstPacket.LSGName?.toString() ?: '')
    updatedFlowFile = session.putAttribute(updatedFlowFile, 'SNo', firstPacket.id?.toString() ?: '')

    updatedFlowFile = session.write(updatedFlowFile, { outputStream ->
        outputStream.write(finalContent.getBytes(StandardCharsets.UTF_8))
    } as OutputStreamCallback)

    session.transfer(updatedFlowFile, REL_SUCCESS)

} catch(Exception e) {
    log.warn('Error inside ExecuteGroovyScript flattening payload: ' + e.getMessage(), e)

    def failFlowFile = session.write(flowFile, { outputStream ->
        outputStream.write(raw.getBytes(StandardCharsets.UTF_8))
    } as OutputStreamCallback)

    session.transfer(failFlowFile, REL_FAILURE)
}

import groovy.json.*
import java.time.Instant
import org.apache.commons.io.IOUtils
import java.nio.charset.*
import java.text.SimpleDateFormat
import java.util.*
import org.apache.commons.lang3.StringEscapeUtils

def flowFile = session.get()
if (flowFile == null) {
    return
}

def flowFiles = [] as List<FlowFile>
def failflowFiles = [] as List<FlowFile>

def raw = ''
def PacketType = ''
def formattedDate = ''
def formattedDate1 = ''

try {
    def data = ''
    session.read(flowFile, { inputStream ->
        data = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    } as InputStreamCallback)

    raw = data

    String cleanedData = StringEscapeUtils.unescapeJava(data).trim().replaceAll('^"|"$','')
    def weatherArray = new JsonSlurper().parseText(cleanedData)

    boolean elseIn = false
    def dateWiseJson = [:]
    def dateWiseArr = []
    Date datee = null

    // Fallback parser that handles optional 'Z' suffix safely
    SimpleDateFormat inputFormat1 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'")
    inputFormat1.setTimeZone(TimeZone.getTimeZone("UTC"))

    SimpleDateFormat inputFormat2 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS")
    inputFormat2.setTimeZone(TimeZone.getTimeZone("UTC"))

    SimpleDateFormat outputFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")
    outputFormat.setTimeZone(TimeZone.getTimeZone("UTC"))

    SimpleDateFormat outputFormat1 = new SimpleDateFormat("yyyy-MM-dd")
    outputFormat1.setTimeZone(TimeZone.getTimeZone("UTC"))

    for (int i = 0; i < weatherArray.size(); i++) {
        def object = weatherArray[i]

        def target2 = [:]
        target2.put("id", object.id)  
        target2.put("LSGName", object.name) 
        target2.put("tenantCode", "EWDS")
        target2.put("vendor", "IMD_NCMRWF")
        target2.put("SNo", object.id.toString())  
        target2.put("District", object.districtname) 
        target2.put("DistrictId", object.districtid) 
        target2.put("thaluk", object.taluk)  
        target2.put("thalukId", object.talukid) 
        target2.put("lsgid", object.lsgid) 
        target2.put("longitude", object.lon)
        target2.put("latitude", object.lat) 

        String temp = String.valueOf(object.TMP_2maboveground)
        Double d = Double.parseDouble(temp)
        Double Celsius = (d - 273.15)
        String afterConversionTemp = String.format(Locale.US, "%.2f", Celsius)

        target2.put("humidity", object.RH_2maboveground.toString())
        target2.put("temperature", afterConversionTemp)
        target2.put("windDirection", object.UGRD_10maboveground.toString())
        target2.put("windSpeed", object.windspeed.toString())
        target2.put("rain_qty", object.APCP_surface.toString())

        // Parse date string handling optional Z suffix
        String timeStr = object.time.toString().trim()
        Date date = null
        try {
            date = inputFormat1.parse(timeStr)
        } catch (Exception ex) {
            date = inputFormat2.parse(timeStr)
        }

        Date date1 = null
        formattedDate = outputFormat.format(date)
        target2.put("date_time", formattedDate)

        datee = date
        formattedDate1 = outputFormat1.format(datee)
        String datee1 = formattedDate1
        target2.put("isodate", formattedDate1)

        if (i < weatherArray.size() - 1) {
            String nextTimeStr = weatherArray[i + 1].time.toString().trim()
            try {
                date1 = inputFormat1.parse(nextTimeStr)
            } catch (Exception ex) {
                date1 = inputFormat2.parse(nextTimeStr)
            }
        } else {
            date1 = date
        }

        if (outputFormat1.format(date).equals(outputFormat1.format(date1))) {
            elseIn = false
            dateWiseArr.add(target2)
        } else {
            elseIn = true
            dateWiseArr.add(target2)
            dateWiseJson.put("packet", dateWiseArr)
            dateWiseJson.put("date", datee1)

            def content = JsonOutput.toJson(dateWiseJson)

            def updatedFlowFile = session.putAttribute(flowFile, 'PacketType', PacketType ?: '')
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'date_', formattedDate1)
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'LSGName', object.name.toString())
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'SNo', object.id.toString())

            def newFlowFile = session.create(updatedFlowFile)
            newFlowFile = session.write(newFlowFile, { outputStream -> 
                outputStream.write(content.getBytes(StandardCharsets.UTF_8))
            } as OutputStreamCallback)

            flowFiles << newFlowFile
            dateWiseArr = []
            dateWiseJson = [:]
        }

        if (i == weatherArray.size() - 1 && !elseIn) {
            dateWiseJson.put("packet", dateWiseArr)
            dateWiseJson.put("date", datee1)

            def content = JsonOutput.toJson(dateWiseJson)

            def updatedFlowFile = session.putAttribute(flowFile, 'PacketType', PacketType ?: '')
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'date_', formattedDate1)
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'LSGName', object.name.toString())
            updatedFlowFile = session.putAttribute(updatedFlowFile, 'SNo', object.id.toString())

            def newFlowFile = session.create(updatedFlowFile)
            newFlowFile = session.write(newFlowFile, { outputStream -> 
                outputStream.write(content.getBytes(StandardCharsets.UTF_8))
            } as OutputStreamCallback)

            flowFiles << newFlowFile
        }
    }

    session.transfer(flowFiles, REL_SUCCESS)
    session.remove(flowFile)

} catch(Exception e) {
    log.warn('Error inside ExecuteGroovyScript: ' + e.getMessage(), e)

    def newFailFlowFile = session.create(flowFile)
    newFailFlowFile = session.write(newFailFlowFile, { outputStream -> 
        outputStream.write(raw.toString().getBytes(StandardCharsets.UTF_8))
    } as OutputStreamCallback)

    failflowFiles << newFailFlowFile
    session.transfer(failflowFiles, REL_FAILURE)
    session.remove(flowFile)
}

import groovy.json.JsonSlurper
import java.time.LocalDate
import java.time.format.DateTimeFormatter
import java.time.temporal.ChronoUnit

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Parse JSON content directly from the FlowFile stream
    def data = null
    session.read(flowFile, { inputStream ->
        def slurper = new JsonSlurper()
        data = slurper.parse(inputStream)
    } as org.apache.nifi.processor.io.InputStreamCallback)

    if (!data) {
        throw new RuntimeException("Failed to parse JSON content: parsed object is null.")
    }

    // 2. Validate and filter based on 'date'
    if (!data.date) {
        log.warn("Payload missing 'date' field. Ignoring record for LSGName: '${data.LSGName}'")
        session.remove(flowFile)
        return
    }

    LocalDate payloadDate = LocalDate.parse(data.date, DateTimeFormatter.ISO_LOCAL_DATE)
    LocalDate currentDate = LocalDate.now()

    // Check if the payload date is in the past -> Completely ignore/remove the FlowFile
    if (payloadDate.isBefore(currentDate)) {
        log.info("Ignoring old date payload. Payload date (${payloadDate}) is before current date (${currentDate}) for LSGName: '${data.LSGName}'. FlowFile will be removed.")
        session.remove(flowFile)
        return
    }

    // 3. Determine table name suffix dynamically (0 for today, 1 for tomorrow, etc., capped at 8)
    long daysDifference = ChronoUnit.DAYS.between(currentDate, payloadDate)
    int tableSuffix = Math.max(0, Math.min((int) daysDifference, 8))
    String tableName = "ncum_tn_district_wisedata_hourly_${tableSuffix}"

    // 4. Define columns with proper PostgreSQL casing/double quotes
    def columns = [
        "id", "\"LSGName\"", "\"tenantCode\"", "vendor", "\"SNo\"", "\"District\"",  
        "\"DistrictId\"", "thaluk", "\"thalukId\"", "lsgid", "longitude",  
        "latitude", "date", "updated_time"
    ]

    def values = [
        data.id ?: 'NULL', 
        data.LSGName ? "'${data.LSGName.replace("'", "''")}'" : 'NULL', 
        data.tenantCode ? "'${data.tenantCode.replace("'", "''")}'" : 'NULL', 
        data.vendor ? "'${data.vendor.replace("'", "''")}'" : 'NULL', 
        data.SNo ? "'${data.SNo.replace("'", "''")}'" : 'NULL', 
        data.District ? "'${data.District.replace("'", "''")}'" : 'NULL', 
        data.DistrictId ? "'${data.DistrictId.replace("'", "''")}'" : 'NULL', 
        data.thaluk ? "'${data.thaluk.replace("'", "''")}'" : 'NULL', 
        data.thalukId ? "'${data.thalukId.replace("'", "''")}'" : 'NULL', 
        data.lsgid ? "'${data.lsgid.replace("'", "''")}'" : 'NULL', 
        data.longitude ?: 'NULL', 
        data.latitude ?: 'NULL', 
        data.date ? "'${data.date}'" : 'NULL',
        data.updated_time ? "'${data.updated_time}'" : 'NULL'
    ]

    // 5. Dynamically loop through hour0 to hour23 for all 5 metrics
    for (int i = 0; i <= 23; i++) {
        columns.add("humidity_hour${i}")
        columns.add("temperature_hour${i}")
        columns.add("\"windDirection_hour${i}\"")
        columns.add("\"windSpeed_hour${i}\"")
        columns.add("\"rain_qty_hour${i}\"")

        values.add(data."humidity_hour${i}" ?: 'NULL')
        values.add(data."temperature_hour${i}" ?: 'NULL')
        values.add(data."windDirection_hour${i}" ?: 'NULL')
        values.add(data."windSpeed_hour${i}" ?: 'NULL')
        values.add(data."rain_qty_hour${i}" ?: 'NULL')
    }

    // 6. Construct the full dynamic INSERT SQL query using the mapped table name
    String sqlAttr = "INSERT INTO ${tableName} (${columns.join(', ')}) VALUES (${values.join(', ')});"

    // Clean up excessive whitespace/newlines
    sqlAttr = sqlAttr.replaceAll("\\s+", " ").trim()

    log.info("Successfully routed query to table '${tableName}' for LSGName: '${data.LSGName}' (Date: ${data.date})")

    // 7. Add SQL query as a FlowFile attribute and route to success
    flowFile = session.putAttribute(flowFile, 'sqlAttr', sqlAttr)
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Failed to parse JSON payload and construct insert SQL", e)
    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // Read and parse the incoming OpenWeatherMap JSON content from the API response
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    // Retrieve district name from the incoming flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Get current GMT time formatted for SQL (system update timestamp)
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // Prepare list to construct dynamic SQL update fields
    List<String> setClauses = []

    // Always include updated_time column in the SQL SET clause
    setClauses.add("updated_time = '${formattedGmtTime}'")

    // Extract weather metrics safely from the OpenWeatherMap payload structure
    String temp        = data.main?.temp?.toString()      ?: "NULL"
    String tempMin     = data.main?.temp_min?.toString()  ?: "NULL"
    String tempMax     = data.main?.temp_max?.toString()  ?: "NULL"
    String humidity    = data.main?.humidity?.toString()  ?: "NULL"
    String windSpeed   = data.wind?.speed?.toString()     ?: "NULL"
    String windDeg     = data.wind?.deg?.toString()       ?: "NULL"

    // Build SQL SET parts matching your reference column names
    // (Adjust column names on the left if your table uses 'temp_min' / 'temp_max' instead of generic ones)
    setClauses.add("temperature = ${temp}")
    setClauses.add("temp_min = ${tempMin}")
    setClauses.add("temp_max = ${tempMax}")
    setClauses.add("humidity = ${humidity}")
    setClauses.add("wind_speed = ${windSpeed}")
    setClauses.add("wind_direction = ${windDeg}")

    // Construct the full SQL UPDATE query string targeting your table
    String sqlUpdateQuery = """
        UPDATE open_weather_actual
        SET ${setClauses.join(',\n')} 
        WHERE district_name = '${districtName.replace("'", "''")}'
    """.trim()

    // Store the compiled query inside the flowfile attribute
    flowFile = session.putAttribute(flowFile, "sql.update.query", sqlUpdateQuery)

    // Transfer to success
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error generating SQL update query for OpenWeatherMap actual payload", e)
    session.transfer(flowFile, REL_FAILURE)
}

import java.nio.file.Paths
import java.nio.file.Files
import java.nio.charset.StandardCharsets

// Retrieve incoming trigger flowfile
def incomingFlowFile = session.get()
if (!incomingFlowFile) return

// Configure your absolute file path here
def filePath = Paths.get("C:\\Own_Weather\\TN_Districts.csv")

try {
    // Check if file exists locally
    if (!Files.exists(filePath)) {
        log.error("CSV file not found at path: ${filePath}")
        session.transfer(incomingFlowFile, REL_FAILURE)
        return
    }

    // Read all lines from the CSV file path
    List<String> lines = Files.readAllLines(filePath, StandardCharsets.UTF_8)
    boolean isHeader = true

    for (String line : lines) {
        // Skip header row
        if (isHeader) {
            isHeader = false
            continue
        }

        if (line.trim().isEmpty()) continue

        // Split columns: id, district_name, district_id, latitude, longitude
        def parts = line.split(",")
        if (parts.length >= 5) {
            def recordId = parts[0].trim()
            def districtName = parts[1].trim()
            def districtId = parts[2].trim()
            def latitude = parts[3].trim()
            def longitude = parts[4].trim()

            // Create a new child FlowFile based on the incoming one using groovyx syntax
            def child = session.create(incomingFlowFile)

            // Set attributes using groovyx shorthand bindings
            child.id = recordId
            child.district_name = districtName
            child.district_id = districtId
            child.latitude = latitude
            child.longitude = longitude

            // Write line content using groovyx string-write shorthand
            child.write("UTF-8", line)

            // Transfer child directly to success relationship using groovyx shortcut
            REL_SUCCESS << child
        }
    }

    // Remove the original trigger flowfile safely
    session.remove(incomingFlowFile)

} catch (Exception e) {
    log.error("Error processing file path in ExecuteGroovyScript", e)
    session.transfer(incomingFlowFile, REL_FAILURE)
}

