import groovy.json.JsonSlurper
import java.time.Instant
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Read and parse incoming OpenWeatherMap Forecast JSON payload
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    def listItems = data.list
    if (!listItems || !(listItems instanceof List)) {
        log.error("Missing 'list' array in OpenWeatherMap Forecast JSON payload.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Retrieve district name from flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // 2. Group 3-hourly forecast items by calendar date string (e.g., "2026-08-26")
    Map<String, Map<String, List<Number>>> dailyGroups = [:]
    def formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd").withZone(ZoneId.of("UTC"))

    listItems.each { item ->
        long dt = item.dt ?: 0
        if (dt == 0) return

        String dateKey = formatter.format(Instant.ofEpochSecond(dt))
        dailyGroups.putIfAbsent(dateKey, [:])
        def dateMap = dailyGroups[dateKey]

        // Extract main weather parameters
        if (item.main) {
            ['temp', 'temp_min', 'temp_max', 'humidity'].each { metric ->
                if (item.main[metric] != null) {
                    dateMap.putIfAbsent(metric, [])
                    dateMap[metric].add((Number) item.main[metric])
                }
            }
        }

        // Extract wind parameters
        if (item.wind) {
            if (item.wind.speed != null) {
                dateMap.putIfAbsent('wind_speed', [])
                dateMap['wind_speed'].add((Number) item.wind.speed)
            }
            if (item.wind.deg != null) {
                dateMap.putIfAbsent('wind_direction', [])
                dateMap['wind_direction'].add((Number) item.wind.deg)
            }
        }
    }

    // 3. Compute Aggregations (Averages for standard metrics, Min/Max extremes where appropriate)
    List<String> sortedDates = dailyGroups.keySet().sort()

    // System update timestamp
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // Set clause array starting with system updated_time
    List<String> setClauses = ["updated_time = '${formattedGmtTime}'"]

    sortedDates.eachWithIndex { dateStr, index ->
        def params = dailyGroups[dateStr]
        String dayKey = "day_${index}" // day_0, day_1, etc.

        // Add forecast date mapping (e.g., time_day_0 = '2026-08-26')
        setClauses.add("time_${dayKey} = '${dateStr}'")

