                    // Average for temp, humidity, wind_speed, wind_direction
                    double sum = values.sum { it.doubleValue() }
                    double avg = sum / values.size()
                    finalVal = Math.round(avg * 100.0) / 100.0
                }

                String colName = "${param}_${dayKey}"
                setClauses.add("${colName} = ${finalVal}")
            }
        }
    }

    // 4. Build SQL UPDATE Statement targeting open_weather_forecast
    String sqlUpdateQuery = """
        UPDATE open_weather_forecast 
        SET ${setClauses.join(',\n')} 
        WHERE district_name = '${districtName.replace("'", "''")}'
    """.trim()

    // Store compiled SQL query inside flowfile attribute
    flowFile = session.putAttribute(flowFile, "sql.update.query", sqlUpdateQuery)

    // Transfer flowfile to success
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error processing OpenWeatherMap forecast data and generating SQL query", e)
    session.transfer(flowFile, REL_FAILURE)
}

