import groovy.json.JsonSlurper
import java.time.Instant
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Read and parse incoming OpenWeatherMap Forecast JSON payload
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    def listItems = data.list
    if (!listItems || !(listItems instanceof List)) {
        log.error("Missing 'list' array in OpenWeatherMap Forecast JSON payload.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Retrieve district name from flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // 2. Group items by Date string -> Hour integer -> Metrics map
    Map<String, Map<Integer, Map<String, Object>>> hourlyDataMap = [:]

    def dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd").withZone(ZoneId.of("UTC"))
    def hourFormatter = DateTimeFormatter.ofPattern("H").withZone(ZoneId.of("UTC"))

    listItems.each { item ->
        long dt = item.dt ?: 0
        if (dt == 0) return

        Instant instant = Instant.ofEpochSecond(dt)
        String dateStr = dateFormatter.format(instant)
        int hourVal = hourFormatter.format(instant).toInteger()

        hourlyDataMap.putIfAbsent(dateStr, [:])
        def dayMap = hourlyDataMap[dateStr]

        Map<String, Object> metrics = [:]
        metrics['temperature'] = item.main?.temp
        metrics['humidity']    = item.main?.humidity
        metrics['windspeed']   = item.wind?.speed
        metrics['winddirection'] = item.wind?.deg

        def rainQty = 0
        if (item.rain) {
            rainQty = item.rain['3h'] ?: item.rain['1h'] ?: 0
        }
        metrics['rain_qty'] = rainQty

        dayMap[hourVal] = metrics
    }

    List<String> sortedDates = hourlyDataMap.keySet().sort()

    // System update timestamp
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // 3. Iterate through each day (up to 8 days: index 0 to 7) and create individual FlowFiles
    sortedDates.eachWithIndex { dateStr, dayIndex ->
        if (dayIndex > 7) return // Max 8 tables mapping from 0 to 7

        def hoursMap = hourlyDataMap[dateStr] ?: [:]

        List<String> setClauses = [
            "updated_time = '${formattedGmtTime}'",
            "date = '${dateStr}'"
        ]

        // Loop through all 24 hours (hour0 to hour23) with forward-fill fallback logic
        for (int h = 0; h < 24; h++) {
            def matchedMetrics = null
            if (hoursMap.containsKey(h)) {
                matchedMetrics = hoursMap[h]
            } else {
                def availableHours = hoursMap.keySet().sort()
                if (!availableHours.isEmpty()) {
                    def closestHour = availableHours.min { Math.abs(it - h) }
                    matchedMetrics = hoursMap[closestHour]
                }
            }

            String hourSuffix = "_hour${h}"

            if (matchedMetrics != null) {
                setClauses.add("humidity${hourSuffix} = ${matchedMetrics['humidity'] != null ? matchedMetrics['humidity'] : 'NULL'}")
                setClauses.add("temperature${hourSuffix} = ${matchedMetrics['temperature'] != null ? matchedMetrics['temperature'] : 'NULL'}")
                setClauses.add("winddirection${hourSuffix} = ${matchedMetrics['winddirection'] != null ? matchedMetrics['winddirection'] : 'NULL'}")
                setClauses.add("windspeed${hourSuffix} = ${matchedMetrics['windspeed'] != null ? matchedMetrics['windspeed'] : 'NULL'}")
                setClauses.add("rain_qty${hourSuffix} = ${matchedMetrics['rain_qty'] != null ? matchedMetrics['rain_qty'] : '0'}")
            } else {
                setClauses.add("humidity${hourSuffix} = NULL")
                setClauses.add("temperature${hourSuffix} = NULL")
                setClauses.add("winddirection${hourSuffix} = NULL")
                setClauses.add("windspeed${hourSuffix} = NULL")
                setClauses.add("rain_qty${hourSuffix} = 0")
            }
        }

        String tableName = "open_weather_forecast_hourly_${dayIndex}"

        String sqlUpdateQuery = """
            UPDATE ${tableName}
            SET ${setClauses.join(',\n')}
            WHERE district_name = '${districtName.replace("'", "''")}'
        """.trim()

        // Clone a new child flowfile for each day/table loop
        def childFlowFile = session.create(flowFile)
        childFlowFile = session.putAttribute(childFlowFile, "target.table.name", tableName)
        childFlowFile = session.putAttribute(childFlowFile, "sql.update.query", sqlUpdateQuery)

        session.transfer(childFlowFile, REL_SUCCESS)
    }

    // 4. Remove original parent flowfile since it's now split into individual table flowfiles
    session.remove(flowFile)

} catch (Exception e) {
    log.error("Error splitting hourly table updates across multiple flowfiles", e)
    session.transfer(flowFile, REL_FAILURE)
}

