import groovy.json.JsonSlurper
import groovy.json.JsonOutput

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Read and parse incoming JSON payload
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    def hourly = data.hourly
    if (!hourly || !hourly.time) {
        log.error("Missing 'hourly' data block in JSON payload.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Map to hold metrics grouped by date string (e.g., "2026-08-25")
    Map<String, Map<String, List<Number>>> dailyGroups = [:]
    def paramKeys = hourly.keySet().findAll { it != 'time' }

    // 2. Group hourly values by date
    for (int i = 0; i < hourly.time.size(); i++) {
        String fullTime = hourly.time[i]
        if (!fullTime || fullTime.length() < 10) continue

        String dateKey = fullTime.substring(0, 10) // Extract "YYYY-MM-DD"

        dailyGroups.putIfAbsent(dateKey, [:])
        def dateMap = dailyGroups[dateKey]

        paramKeys.each { param ->
            def val = hourly[param][i]
            if (val != null) {
                dateMap.putIfAbsent(param, [])
                dateMap[param].add((Number) val)
            }
        }
    }

    // 3. Compute Aggregations (Max for uv_index, Avg for others) and sort dates
    List<String> sortedDates = dailyGroups.keySet().sort()
    Map<String, Map<String, Object>> resultJsonMap = [:]

    sortedDates.eachWithIndex { dateStr, index ->
        def params = dailyGroups[dateStr]
        String dayKey = "day_${index}" // Generates day_0, day_1, etc.

        Map<String, Object> aggregatedRow = [:]
        aggregatedRow['forecast_date'] = dateStr

        params.each { param, values ->
            if (values.isEmpty()) {
                aggregatedRow[param] = null
                return
            }

            if (param == 'uv_index') {
                aggregatedRow[param] = values.max()
            } else {
                double sum = values.sum { it.doubleValue() }
                double avg = sum / values.size()
                aggregatedRow[param] = Math.round(avg * 100.0) / 100.0
            }
        }

        resultJsonMap[dayKey] = aggregatedRow
    }

    // 4. Write back the transformed JSON structure into the flowfile content
    String outputJson = JsonOutput.toJson(resultJsonMap)
    flowFile = session.write(flowFile, { outputStream ->
        outputStream.write(outputJson.getBytes("UTF-8"))
    } as OutputStreamCallback)

    // Transfer to success
    REL_SUCCESS << flowFile

} catch (Exception e) {
    log.error("Error transforming hourly data to day-wise JSON content", e)
    session.transfer(flowFile, REL_FAILURE)
}

