try {
    // 1. Read and parse incoming daily JSON content
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    // Retrieve district name from flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // System update timestamp
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // Set clause array starting with system updated_time
    List<String> setClauses = ["updated_time = '${formattedGmtTime}'"]

    // 2. Loop through each day block (day_0, day_1, day_2, ...)
    data.each { dayKey, dayData ->
        if (dayData && dayData instanceof Map) {
            dayData.each { paramKey, val ->
                // Map forecast_date -> time_day_X, other params -> param_day_X
                String colName = (paramKey == 'forecast_date') ? "time_${dayKey}" : "${paramKey}_${dayKey}"

                if (val == null) {
                    setClauses.add("${colName} = NULL")
                } else if (val instanceof String) {
                    String escapedVal = val.replace("'", "''")
                    setClauses.add("${colName} = '${escapedVal}'")
                } else {
                    setClauses.add("${colName} = ${val}")
                }
            }
        }
    }

    // 3. Build SQL UPDATE Statement
    String sqlUpdateQuery = """
        UPDATE open_meteo_air_quality_forecast 
        SET ${setClauses.join(',\n')} 
        WHERE district_name = '${districtName.replace("'", "''")}'
