import groovy.json.JsonSlurper
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // Read and parse the incoming JSON content from the API response
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    // Retrieve district name from the incoming flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Get current GMT time formatted for SQL (system update timestamp)
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // Safe sanitized district name for SQL strings
    String safeDistrictName = districtName.replace("'", "''")

    // ==========================================
    // 1. BUILD WEATHER ACTUAL UPDATE QUERY
    // ==========================================
    List<String> weatherSetClauses = []
    weatherSetClauses.add("updated_time = '${formattedGmtTime}'")

    def current = data.current
    if (current) {
        String tempC = current.temp_c?.toString() ?: "NULL"
        String windKph = current.wind_kph?.toString() ?: "NULL"
        String windDegree = current.wind_degree?.toString() ?: "NULL"
        String precipMm = current.precip_mm?.toString() ?: "NULL"
        String humidity = current.humidity?.toString() ?: "NULL"
        String uv = current.uv?.toString() ?: "NULL"
        String chanceOfRain = current.chance_of_rain?.toString() ?: "NULL"

        weatherSetClauses.add("temperature = ${tempC}")
        weatherSetClauses.add("wind_speed = ${windKph}")
        weatherSetClauses.add("wind_direction = ${windDegree}")
        weatherSetClauses.add("precipitation = ${precipMm}")
        weatherSetClauses.add("humidity = ${humidity}")
        weatherSetClauses.add("uv = ${uv}")
        weatherSetClauses.add("chance_of_rain = ${chanceOfRain}")
    }

    String weatherSqlUpdateQuery = """
        UPDATE weatherapi_actual
        SET ${weatherSetClauses.join(',\n')} 
        WHERE district_name = '${safeDistrictName}'
    """.trim()


    // ==========================================
    // 2. BUILD AIR QUALITY UPDATE QUERY
    // ==========================================
    List<String> aqSetClauses = []
    aqSetClauses.add("updated_time = '${formattedGmtTime}'")

    if (current && current.air_quality) {
        def aq = current.air_quality

        String pm25 = aq.pm2_5?.toString() ?: "NULL"
        String carbonMonoxide = aq.co?.toString() ?: "NULL"
        String nitrogenDioxide = aq.no2?.toString() ?: "NULL"
        String sulphurDioxide = aq.so2?.toString() ?: "NULL"
        String ozone = aq.o3?.toString() ?: "NULL"
        String uvIndex = current.uv?.toString() ?: "NULL"

        aqSetClauses.add("pm2_5 = ${pm25}")
        aqSetClauses.add("carbon_monoxide = ${carbonMonoxide}")
        aqSetClauses.add("nitrogen_dioxide = ${nitrogenDioxide}")
        aqSetClauses.add("sulphur_dioxide = ${sulphurDioxide}")
        aqSetClauses.add("ozone = ${ozone}")
        aqSetClauses.add("uv_index = ${uvIndex}")
    }

    String aqSqlUpdateQuery = """
        UPDATE weatherapi_air_quality_actual
        SET ${aqSetClauses.join(',\n')} 
        WHERE district_name = '${safeDistrictName}'
    """.trim()


    // ==========================================
    // 3. CREATE TWO SEPARATE FLOWFILES
    // ==========================================

    // FlowFile 1: Assigned the Weather update query attribute
    def weatherFlowFile = flowFile
    weatherFlowFile = session.putAttribute(weatherFlowFile, "sql.update.query", weatherSqlUpdateQuery)
    weatherFlowFile = session.putAttribute(weatherFlowFile, "data.type", "weather_actual")

    // FlowFile 2: Cloned from original, assigned the Air Quality update query attribute
    def aqFlowFile = session.create(flowFile)
    aqFlowFile = session.putAttribute(aqFlowFile, "sql.update.query", aqSqlUpdateQuery)
    aqFlowFile = session.putAttribute(aqFlowFile, "data.type", "air_quality")

    // Transfer both modified FlowFiles to success
    session.transfer(weatherFlowFile, REL_SUCCESS)
    session.transfer(aqFlowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error splitting weather and air quality payloads", e)
    session.transfer(flowFile, REL_FAILURE)
}

