import groovy.json.JsonSlurper
import java.time.Instant
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Read and parse incoming OpenWeatherMap JSON payload
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    def listItems = data.list
    if (!listItems || !(listItems instanceof List)) {
        log.error("Missing 'list' array in OpenWeatherMap JSON payload.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Retrieve district name from flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: ''
    if (districtName.isEmpty()) {
        log.error("Missing 'district_name' attribute on FlowFile.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // 2. Group hourly/list items by date string (e.g., "2026-06-07")
    Map<String, Map<String, List<Number>>> dailyGroups = [:]
    def formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd").withZone(ZoneId.of("UTC"))

    listItems.each { item ->
        long dt = item.dt ?: 0
        if (dt == 0) return

        String dateKey = formatter.format(Instant.ofEpochSecond(dt))
        dailyGroups.putIfAbsent(dateKey, [:])
        def dateMap = dailyGroups[dateKey]

        // Extract AQI from 'main'
        if (item.main && item.main.aqi != null) {
            dateMap.putIfAbsent('aqi', [])
            dateMap['aqi'].add((Number) item.main.aqi)
        }

        // Extract gas/particulate components (co, no, no2, o3, so2, pm2_5, pm10, nh3, etc.)
        if (item.components && item.components instanceof Map) {
            item.components.each { param, val ->
                if (val != null) {
                    dateMap.putIfAbsent(param, [])
                    dateMap[param].add((Number) val)
                }
            }
        }
    }

    // 3. Compute Aggregations (Max for aqi, Avg for components) and sort dates
    List<String> sortedDates = dailyGroups.keySet().sort()

    // System update timestamp
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    // Set clause array starting with system updated_time
    List<String> setClauses = ["updated_time = '${formattedGmtTime}'"]

    sortedDates.eachWithIndex { dateStr, index ->
        def params = dailyGroups[dateStr]
        String dayKey = "day_${index}" // day_0, day_1, etc.

        // Add forecast date mapping (e.g., time_day_0 = '2026-06-07')
        setClauses.add("time_${dayKey} = '${dateStr}'")

        params.each { param, values ->
            if (!values.isEmpty()) {
                def finalVal
                if (param == 'aqi') {
                    finalVal = values.max() // Max AQI for safety/peak metrics
                } else {
                    double sum = values.sum { it.doubleValue() }
                    double avg = sum / values.size()
                    finalVal = Math.round(avg * 100.0) / 100.0
                }

                String colName = "${param}_${dayKey}"
                setClauses.add("${colName} = ${finalVal}")
            }
        }
    }

    // 4. Build SQL UPDATE Statement for open_weather_air_quality_forecast
    String sqlUpdateQuery = """
        UPDATE open_weather_air_quality_forecast 
        SET ${setClauses.join(',\n')} 
        WHERE district_name = '${districtName.replace("'", "''")}'
    """.trim()

    // Store compiled SQL query inside flowfile attribute
    flowFile = session.putAttribute(flowFile, "sql.update.query", sqlUpdateQuery)

    // Transfer flowfile to success (Content remains untouched or you can pass it downstream)
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error processing OpenWeatherMap data and generating SQL query", e)
    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import java.time.Instant
import java.time.ZoneId
import java.time.ZonedDateTime
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

try {
    // Read and parse the incoming OpenWeatherMap JSON payload
    String jsonContent = flowFile.read().getText("UTF-8")
    def slurper = new JsonSlurper()
    def data = slurper.parseText(jsonContent)

    // Retrieve district name from incoming flowfile attributes
    String districtName = flowFile.attributes['district_name'] ?: 'Karur'
    String safeDistrictName = districtName.replace("'", "''")

    // Get current GMT time formatted for SQL update
    def gmtNow = ZonedDateTime.now(ZoneId.of("GMT"))
    String formattedGmtTime = gmtNow.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

    def listItems = data?.list
    if (!listItems || listItems.isEmpty()) {
        log.error("No list items found in OpenWeatherMap air quality payload.")
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Process tables from index 0 to 7 (8 tables total)
    int totalDays = 8

    for (int dayIndex = 0; dayIndex < totalDays; dayIndex++) {
        int startIndex = dayIndex * 24

        // Check if the JSON has enough items for this day index
        if (listItems.size() <= startIndex) {
            log.warn("Not enough data points for day index ${dayIndex}. Stopping loop.")
            break
        }

        String tableName = "open_weather_air_quality_forecast_hourly_${dayIndex}"
        List<String> setClauses = []
        setClauses.add("updated_time = '${formattedGmtTime}'")

        // Map each hour of the specific day (0 to 23)
        for (int hour = 0; hour < 24; hour++) {
            int currentIdx = startIndex + hour
            if (currentIdx >= listItems.size()) break

            def entry = listItems[currentIdx]
            String suffix = "hour${hour}".toString()

            // Extract Unix timestamp 'dt' and convert to standard date string (YYYY-MM-DD HH:mm:ss)
            long dtEpoch = entry.dt ? entry.dt.toLong() : 0L
            String formattedDateTime = ""
            String dateOnly = ""

            if (dtEpoch > 0) {
                ZonedDateTime zdt = ZonedDateTime.ofInstant(Instant.ofEpochSecond(dtEpoch), ZoneId.of("GMT"))
                formattedDateTime = zdt.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
                dateOnly = zdt.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))
            }

            // Extract components map values safely
            def comp = entry.components ?: [:]
            String co   = comp.co?.toString()   ?: "NULL"
            String no   = comp.no?.toString()   ?: "NULL"
            String no2  = comp.no2?.toString()  ?: "NULL"
            String o3   = comp.o3?.toString()   ?: "NULL"
            String so2  = comp.so2?.toString()  ?: "NULL"
            String pm25 = comp.pm2_5?.toString() ?: "NULL"
            String pm10 = comp.pm10?.toString() ?: "NULL"
            String nh3  = comp.nh3?.toString()  ?: "NULL"
            String aqi  = entry.main?.aqi?.toString() ?: "NULL"

            // Set the 'date' field on the first hour block
            if (hour == 0 && !dateOnly.isEmpty()) {
                setClauses.add("date = '${dateOnly}'")
            }

            // Assign hourly metric columns mapping your exact table schemas
            setClauses.add("aqi_${suffix} = ${aqi}")
            setClauses.add("co_${suffix} = ${co}")
            setClauses.add("no_${suffix} = ${no}")
            setClauses.add("no2_${suffix} = ${no2}")
            setClauses.add("o3_${suffix} = ${o3}")
            setClauses.add("so2_${suffix} = ${so2}")
            setClauses.add("pm2_5_${suffix} = ${pm25}")
            setClauses.add("pm10_${suffix} = ${pm10}")
            setClauses.add("nh3_${suffix} = ${nh3}")
        }

        // Construct the SQL UPDATE statement for the current day table
        String sqlUpdateQuery = """
            UPDATE ${tableName}
            SET ${setClauses.join(',\n')}
            WHERE district_name = '${safeDistrictName}'
        """.trim()

        // Clone or use the original FlowFile for each table iteration stream
        def targetFlowFile = (dayIndex == 0) ? flowFile : session.create(flowFile)
        targetFlowFile = session.putAttribute(targetFlowFile, "sql.update.query", sqlUpdateQuery)
        targetFlowFile = session.putAttribute(targetFlowFile, "target.table", tableName)
        targetFlowFile = session.putAttribute(targetFlowFile, "forecast.day.index", dayIndex.toString())

        // Transfer the generated FlowFile for database execution (e.g., PutSQL)
        session.transfer(targetFlowFile, REL_SUCCESS)
    }

} catch (Exception e) {
    log.error("Error generating multi-day OpenWeatherMap air quality forecast update queries", e)
    session.transfer(flowFile, REL_FAILURE)
}
